**Risk:** Without security headers, the app is vulnerable to:
- XSS attacks (no `X-Content-Type-Options`)
- Clickjacking (no `X-Frame-Options`)
- MIME type sniffing vulnerabilities

**Recommendation:**
```javascript
// Install helmet: npm install helmet
const helmet = require('helmet');
app.use(helmet());

// Or manually add essential headers:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

---

### 2. **No Input Validation**
Even though endpoints currently don't accept parameters, there's no validation infrastructure in place.

**Recommendation:**
```javascript
// Install express-validator: npm install express-validator
const { body, param, validationResult } = require('express-validator');

app.get('/users/:id', [
  param('id').isInt({ min: 1 }).toInt()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // proceed with handler
});
```

